for (const item of $input.all()) {
  const body = item.json.body || {};
  let text = item.json.contract_text || body.contract_text || item.json.text || item.json.data || '';
  item.json.contract_text = text;
}
return $input.all();

// === REDACTION 4 CAP (JS) ===
// stripDiacritics: chuyen tieeng Viet co dau -> khong dau de regex de match
function stripDiacritics(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
}

function redact(text) {
  // Cap 1 - PII Email
  text = text.replace(/[\w.+-]+@[\w-]+\.\w+/g, '[email redact]');
  // Cap 2 - Ma so thue (MST): match "Ma so thue:" ca co dau va khong dau
  const noAccent = stripDiacritics(text);
  const mstRegex = /(Ma\s*so\s*thue:\s*)(\d{10})/gi;
  let m;
  while ((m = mstRegex.exec(noAccent)) !== null) {
    text = text.substring(0, m.index) + m[1] + '[MST redact]' + text.substring(m.index + m[0].length);
    break;
  }
  // Cap 1 - PII SDT
  text = text.replace(/\b0\d{9,10}\b/g, '0xxx');
  // Cap 2 - Gia tri tai chinh
  text = text.replace(/\b\d{1,3}(?:[.,]\d{3})+(?:\s*(?:VND|VNĐ|dong|đong))?\b/gi, '[gia tri redact]');
  // Cap 3 - Nhay cam nghiep vu: ten nguoi dai dien (Họ + Văn/Thị + Tên)
  text = text.replace(/([A-ZÀ-Ỹ][a-zà-ỹ]+)\s+V[aă]n\s+[A-ZÀ-Ỹ][a-zà-ỹ]+/g, 'Dai dien Ben A');
  text = text.replace(/([A-ZÀ-Ỹ][a-zà-ỹ]+)\s+Th[iị]\s+[A-ZÀ-Ỹ][a-zà-ỹ]+/g, 'Dai dien Ben B');
  // Cap 4 - Gate To mat: DUNG workflow
  const lower = stripDiacritics(text).toLowerCase();
  for (const kw of ['toi mat', 'tuyet mat', 'bi mat nha nuoc']) {
    if (lower.includes(kw)) {
      throw new Error('SECURITY GATE CAP 4: ' + kw + ' -> STOP, yeu cau AI Local/on-prem');
    }
  }
  return text;
}

for (const item of $input.all()) {
  const raw = item.json.data || item.json.text || item.json.contract_text || '';
  item.json.contract_id = 'HD-' + new Date().getFullYear() + '-UPLOAD';
  item.json.contract_text = raw;
  item.json.contract_redacted = redact(raw);
  item.json.contract_original = raw;
}
return $input.all();

// === SCHEMA VALIDATION theo clause.schema.json ===
const REQUIRED_TOP = ['contract_id', 'metadata', 'clauses', 'confidence_score', 'need_review'];
const REQUIRED_META = ['ben_a', 'ben_b', 'ngay_ky', 'loai_hop_dong'];
const REQUIRED_CLAUSE = ['id', 'tieu_de', 'noi_dung', 'evidence', 'confidence_score', 'need_review'];
const REQUIRED_EVIDENCE = ['verbatim_quote'];

for (const item of $input.all()) {
  const errors = [];
  let textContent = '';
  try {
    const cands = item.json.candidates || [];
    if (cands.length > 0) {
      const parts = (cands[0].content && cands[0].content.parts) || [];
      textContent = (parts[0] && parts[0].text) || '';
    }
  } catch (e) { errors.push('Loi doc response AI: ' + e.message); }

  let parsed = {};
  if (textContent) {
    try { parsed = (typeof textContent === 'string') ? JSON.parse(textContent) : textContent; }
    catch (e) { errors.push('Loi parse JSON AI: ' + e.message); }
  }

  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && Object.keys(parsed).length > 0) {
    for (const f of REQUIRED_TOP) if (!(f in parsed)) errors.push('Thieu top-level field: ' + f);
    const meta = parsed.metadata || {};
    for (const f of REQUIRED_META) if (!(f in meta)) errors.push('Thieu metadata field: ' + f);
    const clauses = Array.isArray(parsed.clauses) ? parsed.clauses : [];
    if (clauses.length < 3) errors.push('clauses minItems 3 (hien ' + clauses.length + ')');
    for (const c of clauses) {
      for (const f of REQUIRED_CLAUSE) if (!(f in c)) errors.push('Thieu clause field: ' + f);
      const ev = c.evidence || {};
      for (const f of REQUIRED_EVIDENCE) if (!(f in ev)) errors.push('Clause ' + (c.id||'?') + ' thieu evidence.' + f);
      if (typeof c.confidence_score !== 'number' || c.confidence_score < 0 || c.confidence_score > 1)
        errors.push('Clause ' + (c.id||'?') + ' confidence_score phai 0-1');
      if (typeof c.need_review !== 'boolean') errors.push('Clause ' + (c.id||'?') + ' need_review phai boolean');
    }
    if (typeof parsed.confidence_score !== 'number' || parsed.confidence_score < 0 || parsed.confidence_score > 1)
      errors.push('top-level confidence_score phai 0-1');
    if (typeof parsed.need_review !== 'boolean') errors.push('top-level need_review phai boolean');
    item.json.clauses = clauses;
    item.json.metadata = meta;
    item.json.extracted_data = parsed;
  } else {
    errors.push('Output AI khong phai Object JSON hop le');
  }

  item.json._schema_ok = (errors.length === 0);
  item.json._schema_errors = errors;
  item.json._retry_count = (item.json._retry_count || 0);
}
return $input.all();

// === EVIDENCE verbatim + OMISSION (semantics) ===
// stripDiacritics: bo dau tieng Viet de regex de match chinh xac
function stripDiacritics(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
}
// Moi group: testFn nhan clause title + summary + evidence da strip dau va lower-case.
// Omission check chi danh dau thieu coverage; red flag check nam o node Policy Review.
const REQUIRED_GROUPS = [
  { group: 'TC01 - Đối tượng & Phạm vi', test: t => /\bdoi tuong\b/i.test(t) || /\bpham vi\b/i.test(t) || /\bban giao\b/i.test(t) },
  { group: 'TC02 - Giá trị & Thanh toán', test: t => /\bgia tri\b/i.test(t) || /\bthanh toan\b/i.test(t) || /\bhoa don\b/i.test(t) },
  { group: 'TC03 - Nghĩa vụ các Bên', test: t => /\bnghia vu\b/i.test(t) || /\bcam ket\b/i.test(t) || /\bphoi hop\b/i.test(t) },
  { group: 'TC04 - Thời hạn & Tiến độ', test: t => /\bthoi han\b/i.test(t) || /\btien do\b/i.test(t) || /\bmoc ban giao\b/i.test(t) },
  { group: 'TC05 - Chấm dứt & Hậu quả chấm dứt', test: t => /\bcham dut\b/i.test(t) || /\bdon phuong\b/i.test(t) || /\bhau qua cham dut\b/i.test(t) },
  { group: 'TC06 - Bảo mật thông tin', test: t => /\bbao mat\b/i.test(t) || /\btiet lo\b/i.test(t) || /\bthong tin bao mat\b/i.test(t) },
  { group: 'TC07 - Sở hữu trí tuệ', test: t => /\bso huu tri tue\b/i.test(t) || /\bban quyen\b/i.test(t) || /\bsource code\b/i.test(t) },
  { group: 'TC08 - Bảo hành & Giới hạn trách nhiệm', test: t => /\bbao hanh\b/i.test(t) || /\bgioi han trach nhiem\b/i.test(t) || /\bboi thuong\b/i.test(t) },
  { group: 'TC10 - Bất khả kháng', test: t => /\bbat kha khang\b/i.test(t) || /\bdich benh\b/i.test(t) || /\bthien tai\b/i.test(t) },
  { group: 'TC11 - Phạt vi phạm', test: t => /\bphat vi pham\b/i.test(t) || /\bmuc phat\b/i.test(t) },
  { group: 'TC12 - Tranh chấp & Luật áp dụng', test: t => /\btranh chap\b/i.test(t) || /\bluat ap dung\b/i.test(t) || /\btoa an\b/i.test(t) || /\btrong tai\b/i.test(t) }
];

for (const item of $input.all()) {
  const clauses = item.json.clauses || [];
  const contract = item.json.contract_original || item.json.contract_text || '';
  const hallucinations = [];
  for (const c of clauses) {
    const quote = (c.evidence && c.evidence.verbatim_quote) || '';
    if (quote && !contract.includes(quote)) {
      hallucinations.push({ id: c.id, flag: 'hallucination', reason: 'verbatim_quote KHÔNG có nguyên văn trong hợp đồng gốc' });
    }
  }

  // Strip dau moi clause title & noi dung de match chinh xac
  const clauseTexts = clauses.map(c => stripDiacritics((c.id || '') + ' ' + (c.tieu_de || '') + ' ' + (c.noi_dung || '') + ' ' + ((c.evidence && c.evidence.verbatim_quote) || '')).toLowerCase());
  const presentGroups = [];
  const omissions = [];
  for (const g of REQUIRED_GROUPS) {
    const hit = clauseTexts.some(t => g.test(t));
    if (hit) presentGroups.push(g.group); else omissions.push(g.group);
  }

  item.json.evidence_checked = {
    hallucinations, omissions, present_groups: presentGroups, n_clauses: clauses.length
  };
}
return $input.all();

// === POLICY REVIEW vs checklist-rui-ro.md (Knowledge Base) ===
// Rule-based second pass: review ca dieu khoan da co, gan red flag, va tao de xuat sua.
function stripDiacritics(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
}
function any(reList, text) { return reList.some(re => re.test(text)); }
const KB_RULES = [
  { id: 'TC01', label: 'Scope creep / phát sinh không kiểm soát', kw: [/cong viec khac theo yeu cau/i, /khong tinh them chi phi/i, /phat sinh.*khong.*phi/i, /theo yeu cau cua ben a/i], sev: 'HIGH', redline: 'Mọi công việc phát sinh ngoài phụ lục/phạm vi đã chốt phải được hai bên thống nhất bằng phụ lục bổ sung và được tính phí riêng.' },
  { id: 'TC02', label: 'Thanh toán cảm tính hoặc mốc thanh toán mơ hồ', kw: [/hai long/i, /hoan toan hai long/i, /thoi han hop ly/i, /sau khi.*chap nhan.*don phuong/i], sev: 'HIGH', redline: 'Quy định mốc thanh toán định lượng, thời hạn phản hồi nghiệm thu 05 ngày làm việc, cơ chế deemed acceptance và lãi phạt chậm trả.' },
  { id: 'TC03', label: 'Đổ toàn bộ nghĩa vụ/trách nhiệm sang một bên', kw: [/chiu toan bo trach nhiem/i, /bat ke loi cua ben a/i, /khong duoc thay doi nhan su/i, /phat.*moi lan thay doi nhan su/i], sev: 'HIGH', redline: 'Mỗi bên chịu trách nhiệm trong phạm vi lỗi và nghĩa vụ của mình; thay đổi nhân sự được phép nếu thông báo trước và nhân sự thay thế tương đương.' },
  { id: 'TC04', label: 'Tiến độ đóng đinh không trừ lỗi bên kia', kw: [/bat ke thoi gian ben a/i, /khong duoc gia han/i, /ngay hoan tat co dinh/i, /dung tien do bat ke/i], sev: 'MED', redline: 'Tiến độ phải được gia hạn tương ứng khi Bên A chậm cung cấp thông tin, mặt bằng, phê duyệt hoặc khi có bất khả kháng.' },
  { id: 'TC05', label: 'Đơn phương chấm dứt/gia hạn bất bình đẳng', kw: [/don phuong cham dut.*khong phai boi thuong/i, /ben a co quyen don phuong/i, /ben b.*phat 100/i, /don phuong gia han/i, /khong can.*dong y/i], sev: 'HIGH', redline: 'Hai bên chỉ được đơn phương chấm dứt khi bên kia vi phạm nghiêm trọng và không khắc phục trong 15 ngày; gia hạn phải bằng văn bản có đồng ý của cả hai bên.' },
  { id: 'TC06', label: 'Bảo mật vô thời hạn hoặc phạt siêu ngạch', kw: [/vo thoi han/i, /vinh vien/i, /moi thong tin.*bao mat/i, /phat.*5\.?000\.?000\.?000/i], sev: 'HIGH', redline: 'Giới hạn nghĩa vụ bảo mật trong thời hạn hợp đồng và 02-03 năm sau chấm dứt; loại trừ thông tin công khai/hợp pháp/tự phát triển.' },
  { id: 'TC07', label: 'Chuyển giao IP trước khi thanh toán đủ', kw: [/thuoc ve ben a ngay tu thoi diem tao ra/i, /chuyen giao.*ngay khi tao ra/i, /source code.*thuoc ve ben a/i, /quyen so huu tri tue.*truoc.*thanh toan/i], sev: 'HIGH', redline: 'IP/kết quả công việc chỉ chuyển giao sau khi Bên A thanh toán đủ; Bên B giữ quyền với Background IP/công cụ có trước.' },
  { id: 'TC08', label: 'Bồi thường không giới hạn hoặc thiệt hại gián tiếp', kw: [/khong gioi han/i, /khong co muc tran/i, /vo han/i, /thiet hai gian tiep/i, /mat doanh thu/i, /mat co hoi kinh doanh/i, /suy giam uy tin/i], sev: 'HIGH', redline: 'Tổng trách nhiệm bồi thường không vượt quá 100% giá trị hợp đồng/giá trị đã nhận và loại trừ thiệt hại gián tiếp, hệ quả, lợi nhuận bị mất.' },
  { id: 'TC09', label: 'Tự động gia hạn với cửa sổ hủy bất lợi', kw: [/tu dong gia han/i, /auto-renew/i, /thong bao khong gia han.*60 ngay/i, /tru khi.*bao huy/i], sev: 'MED', redline: 'Không áp dụng tự động gia hạn mặc định; chỉ gia hạn bằng phụ lục/văn bản trước khi hết hạn.' },
  { id: 'TC10', label: 'Bất khả kháng quá hẹp hoặc thủ tục mất quyền', kw: [/bat kha khang.*chi gom/i, /loai tru.*dich benh/i, /loai tru.*thay doi.*luat/i, /24 gio.*mat quyen/i], sev: 'MED', redline: 'Mở rộng bất khả kháng gồm dịch bệnh, thay đổi luật/chính sách, sự cố hạ tầng; thời hạn thông báo hợp lý 07 ngày làm việc.' },
  { id: 'TC11', label: 'Phạt vi phạm vượt trần hoặc phạt trùng', kw: [/phat vi pham.*(20|30|50)%/i, /(20|30|50)%.*gia tri hop dong/i, /phat trung lap/i, /phat theo ngay.*khong gioi han/i], sev: 'HIGH', redline: 'Mức phạt vi phạm không vượt quá 8% giá trị phần nghĩa vụ bị vi phạm theo Điều 301 Luật Thương mại và không phạt trùng lắp.' },
  { id: 'TC12', label: 'Cơ quan giải quyết tranh chấp bất lợi', kw: [/toa an nhan dan tinh ca mau/i, /toa an.*tinh xa/i, /trong tai quoc te/i, /siac/i, /hkiac/i], sev: 'HIGH', redline: 'Ưu tiên thương lượng/hòa giải; nếu không thành, giải quyết tại Tòa án có thẩm quyền tại nơi doanh nghiệp đặt trụ sở hoặc cơ quan phù hợp tại Việt Nam.' }
];

for (const item of $input.all()) {
  const clauses = item.json.clauses || [];
  const reviewed = clauses.map(c => {
    // Strip dau truoc khi match
    const text = stripDiacritics((c.id||'') + ' ' + (c.tieu_de||'') + ' ' + (c.noi_dung||'') + ' ' + ((c.evidence && c.evidence.verbatim_quote)||'')).toLowerCase();
    const matched = [];
    for (const r of KB_RULES) if (any(r.kw, text)) matched.push(r);
    const isHigh = matched.some(m => m.sev === 'HIGH') || c.severity === 'HIGH';
    const hasMed = matched.some(m => m.sev === 'MED') || c.severity === 'MED';
    const newSev = isHigh ? 'HIGH' : (hasMed ? 'MED' : (c.severity || 'LOW'));
    const existingDeXuat = c.de_xuat && c.de_xuat.trim() && !c.de_xuat.includes('Cần điều chỉnh') ? c.de_xuat : '';
    const kbDeXuat = matched.length ? matched.map(m => '[' + m.id + ' - ' + m.label + '] ' + m.redline).join(' | ') : '';
    return Object.assign({}, c, {
      kb_matches: matched.map(m => m.id),
      red_flags: matched.map(m => ({ id: m.id, label: m.label, severity: m.sev, redline: m.redline })),
      severity: newSev,
      de_xuat: kbDeXuat || existingDeXuat || 'Điều khoản đã có nhưng cần rà lại câu chữ, mốc thời gian, trách nhiệm và chế tài để tránh diễn giải mập mờ.'
    });
  });
  item.json.clauses_reviewed = reviewed;
  item.json.red_flags = reviewed.flatMap(c => (c.red_flags || []).map(r => Object.assign({ clause_id: c.id, tieu_de: c.tieu_de, evidence: (c.evidence && c.evidence.verbatim_quote) || '' }, r)));
}
return $input.all();

// === REPORT & SCORING + BUILD report.docx (OOXML ZIP) ===
const SEV = { HIGH: '\uD83D\uDD34', MED: '\uD83D\uDFE1', LOW: '\uD83D\uDCA1' };
const AMP = String.fromCharCode(38) + 'amp;';
const LT  = String.fromCharCode(38) + 'lt;';
const GT  = String.fromCharCode(38) + 'gt;';
const QUOT = String.fromCharCode(38) + 'quot;';
const APOS = String.fromCharCode(38) + 'apos;';

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, AMP).replace(/</g, LT).replace(/>/g, GT)
    .replace(/"/g, QUOT).replace(/'/g, APOS);
}
function run(text, opts = {}) {
  const rPr = [
    '<w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/>',
    opts.bold ? '<w:b/>' : '',
    opts.italic ? '<w:i/>' : '',
    opts.underline ? '<w:u w:val="single"/>' : '',
    opts.color ? '<w:color w:val="' + opts.color + '"/>' : '',
    '<w:sz w:val="' + (opts.size || 28) + '"/>',
    '<w:szCs w:val="' + (opts.size || 28) + '"/>'
  ].join('');
  const pieces = String(text == null ? '' : text).split('\n');
  return '<w:r><w:rPr>' + rPr + '</w:rPr>' + pieces.map((piece, idx) =>
    (idx ? '<w:br/>' : '') + '<w:t xml:space="preserve">' + esc(piece) + '</w:t>'
  ).join('') + '</w:r>';
}
function para(text, opts = {}) {
  const jc = opts.align ? '<w:jc w:val="' + opts.align + '"/>' : '';
  const spacing = '<w:spacing w:before="' + (opts.before || 0) + '" w:after="' + (opts.after == null ? 120 : opts.after) + '" w:line="276" w:lineRule="auto"/>';
  const ind = opts.firstLine ? '<w:ind w:firstLine="' + opts.firstLine + '"/>' : '';
  const keepNext = opts.keepNext ? '<w:keepNext/>' : '';
  const style = opts.style ? '<w:pStyle w:val="' + opts.style + '"/>' : '';
  return '<w:p><w:pPr>' + style + jc + spacing + ind + keepNext + '</w:pPr>' + run(text, opts) + '</w:p>';
}
function multiPara(parts, opts = {}) {
  const jc = opts.align ? '<w:jc w:val="' + opts.align + '"/>' : '';
  const spacing = '<w:spacing w:before="' + (opts.before || 0) + '" w:after="' + (opts.after == null ? 120 : opts.after) + '" w:line="276" w:lineRule="auto"/>';
  return '<w:p><w:pPr>' + jc + spacing + '</w:pPr>' + parts.map(p => run(p.text, p)).join('') + '</w:p>';
}
function cell(text, width, opts = {}) {
  const fill = opts.fill ? '<w:shd w:fill="' + opts.fill + '"/>' : '';
  const vAlign = '<w:vAlign w:val="' + (opts.valign || 'center') + '"/>';
  const margins = '<w:tcMar><w:top w:w="90" w:type="dxa"/><w:left w:w="110" w:type="dxa"/><w:bottom w:w="90" w:type="dxa"/><w:right w:w="110" w:type="dxa"/></w:tcMar>';
  return '<w:tc><w:tcPr><w:tcW w:w="' + width + '" w:type="dxa"/>' + fill + vAlign + margins + '</w:tcPr>' +
    para(text, { align: opts.align || 'left', bold: opts.bold, size: opts.size || 24, after: 0 }) + '</w:tc>';
}
function table(rows, widths) {
  const borders = '<w:tblBorders><w:top w:val="single" w:sz="6" w:color="9CA3AF"/><w:left w:val="single" w:sz="6" w:color="9CA3AF"/><w:bottom w:val="single" w:sz="6" w:color="9CA3AF"/><w:right w:val="single" w:sz="6" w:color="9CA3AF"/><w:insideH w:val="single" w:sz="4" w:color="D1D5DB"/><w:insideV w:val="single" w:sz="4" w:color="D1D5DB"/></w:tblBorders>';
  const grid = '<w:tblGrid>' + widths.map(w => '<w:gridCol w:w="' + w + '"/>').join('') + '</w:tblGrid>';
  return '<w:tbl><w:tblPr><w:tblW w:w="9360" w:type="dxa"/><w:tblLayout w:type="fixed"/>' + borders + '</w:tblPr>' + grid +
    rows.map(row => '<w:tr>' + row.map((c, i) => cell(c.text, widths[i], c)).join('') + '</w:tr>').join('') + '</w:tbl>' +
    para('', { after: 120 });
}

// === OOXML ZIP BUILDER (STORE method) ===
const crcTable = [];
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
  crcTable[n] = c;
}
function crc32(buf) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) crc = crcTable[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  return (crc ^ 0xFFFFFFFF) >>> 0;
}
function buildZip(files) {
  const localParts = [], centralParts = [];
  let offset = 0;
  for (const f of files) {
    const nameBuf = Buffer.from(f.name, 'utf8');
    const crc = crc32(f.data);
    const size = f.data.length;
    const local = Buffer.alloc(30 + nameBuf.length);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4); local.writeUInt16LE(0, 6); local.writeUInt16LE(0, 8);
    local.writeUInt16LE(0, 10); local.writeUInt16LE(0, 12);
    local.writeUInt32LE(crc, 14); local.writeUInt32LE(size, 18); local.writeUInt32LE(size, 22);
    local.writeUInt16LE(nameBuf.length, 26); local.writeUInt16LE(0, 28);
    nameBuf.copy(local, 30);
    const central = Buffer.alloc(46 + nameBuf.length);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4); central.writeUInt16LE(20, 6); central.writeUInt16LE(0, 8);
    central.writeUInt16LE(0, 10); central.writeUInt16LE(0, 12); central.writeUInt16LE(0, 14);
    central.writeUInt32LE(crc, 16); central.writeUInt32LE(size, 20); central.writeUInt32LE(size, 24);
    central.writeUInt16LE(nameBuf.length, 28); central.writeUInt16LE(0, 30); central.writeUInt16LE(0, 32);
    central.writeUInt16LE(0, 34); central.writeUInt16LE(0, 36); central.writeUInt32LE(0, 38);
    central.writeUInt32LE(offset, 42);
    nameBuf.copy(central, 46);
    localParts.push(local, f.data);
    centralParts.push(central);
    offset += local.length + f.data.length;
  }
  const localBuf = Buffer.concat(localParts);
  const centralBuf = Buffer.concat(centralParts);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4); eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(files.length, 8); eocd.writeUInt16LE(files.length, 10);
  eocd.writeUInt32LE(centralBuf.length, 12);
  eocd.writeUInt32LE(localBuf.length, 16);
  eocd.writeUInt16LE(0, 20);
  return Buffer.concat([localBuf, centralBuf, eocd]);
}

